static void vu_grow_L_S_Snap(L_S_Snap *l) {
    if (l->cap > (int64_t)(PTRDIFF_MAX / sizeof(T_Snap) / 2)) vu_oom();
    int64_t c = l->cap ? l->cap * 2 : 4;
    T_Snap *d = (T_Snap *)realloc(l->data, (size_t)c * sizeof(T_Snap));
    if (!d) vu_oom();
    l->data = d;
    l->cap = c;
}
