        __atomic_store_n(&vu_chunks_L_S_LspChange, next_chunk, __ATOMIC_RELAXED);
        vu_free_L_S_LspChange = (L_S_LspChange *)c;
        vu_nfree_L_S_LspChange = VU_TAKE;   /* (at most; it only decides when to give some back) */
